-- NexTech v2. MySQL 8.0.16+ / MariaDB 10.6+
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS roles (code VARCHAR(20) PRIMARY KEY, name VARCHAR(60) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer', phone VARCHAR(30) NOT NULL DEFAULT '', auth_version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at VARCHAR(30) NOT NULL, FOREIGN KEY(role) REFERENCES roles(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (slug VARCHAR(40) PRIMARY KEY, name VARCHAR(90) NOT NULL, icon VARCHAR(30) NOT NULL, position INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTO_INCREMENT, sku VARCHAR(80) NOT NULL UNIQUE, category VARCHAR(40) NOT NULL, name VARCHAR(220) NOT NULL, brand VARCHAR(90) NOT NULL, description TEXT NOT NULL, image VARCHAR(1500) NOT NULL DEFAULT '', source_url VARCHAR(1500) NOT NULL DEFAULT '', source_checked VARCHAR(20) NOT NULL DEFAULT '', price INTEGER NOT NULL DEFAULT 0, compare_price INTEGER NOT NULL DEFAULT 0, stock INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, verified INTEGER NOT NULL DEFAULT 0, supplier_id INTEGER, updated_at VARCHAR(30) NOT NULL, CHECK(price>=0 AND stock>=0), FOREIGN KEY(category) REFERENCES categories(slug), FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS product_specs (product_id INTEGER NOT NULL, spec_key VARCHAR(80) NOT NULL, spec_value VARCHAR(500) NOT NULL, PRIMARY KEY(product_id,spec_key), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS cart (user_id INTEGER NOT NULL, product_id INTEGER NOT NULL, qty INTEGER NOT NULL CHECK(qty BETWEEN 1 AND 99), PRIMARY KEY(user_id,product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL, product_id INTEGER NOT NULL, PRIMARY KEY(user_id,product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS addresses (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, label VARCHAR(50) NOT NULL, recipient VARCHAR(120) NOT NULL, phone VARCHAR(30) NOT NULL, street VARCHAR(250) NOT NULL, colony VARCHAR(120) NOT NULL, city VARCHAR(120) NOT NULL, state VARCHAR(120) NOT NULL, postal_code VARCHAR(10) NOT NULL, notes VARCHAR(500) NOT NULL DEFAULT '', FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS orders (id VARCHAR(40) PRIMARY KEY, user_id INTEGER NOT NULL, status VARCHAR(30) NOT NULL, payment_status VARCHAR(30) NOT NULL, provider VARCHAR(30) NOT NULL, payment_id VARCHAR(190) UNIQUE, checkout_url TEXT, tax_rate_bp INTEGER NOT NULL DEFAULT 1600, tax INTEGER NOT NULL DEFAULT 0, net_total INTEGER NOT NULL DEFAULT 0, subtotal INTEGER NOT NULL, shipping INTEGER NOT NULL, total INTEGER NOT NULL, address TEXT NOT NULL, idempotency_key VARCHAR(100) NOT NULL UNIQUE, tracking VARCHAR(200) NOT NULL DEFAULT '', notes TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, updated_at VARCHAR(30) NOT NULL, CHECK(total=subtotal+shipping AND total>=0), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(40) NOT NULL, product_id INTEGER NOT NULL, sku VARCHAR(80) NOT NULL, name VARCHAR(220) NOT NULL, price INTEGER NOT NULL, qty INTEGER NOT NULL, image VARCHAR(1500) NOT NULL DEFAULT '', CHECK(qty>0 AND price>=0), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_events (id INTEGER PRIMARY KEY AUTO_INCREMENT, order_id VARCHAR(40) NOT NULL, message VARCHAR(500) NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS reset_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(64) PRIMARY KEY, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, action VARCHAR(100) NOT NULL, detail TEXT NOT NULL, created_at VARCHAR(30) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_movements (id INTEGER PRIMARY KEY AUTO_INCREMENT, product_id INTEGER NOT NULL, user_id INTEGER NOT NULL, order_id VARCHAR(40), quantity INTEGER NOT NULL, before_stock INTEGER NOT NULL, after_stock INTEGER NOT NULL, reason VARCHAR(120) NOT NULL, created_at VARCHAR(30) NOT NULL, CHECK(after_stock=before_stock+quantity AND after_stock>=0), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS payment_events (event_id VARCHAR(190) PRIMARY KEY, created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX idx_products_category ON products(category,active);
CREATE INDEX idx_orders_user ON orders(user_id,created_at);
CREATE INDEX idx_orders_date ON orders(created_at,status);
CREATE INDEX idx_movements_product ON inventory_movements(product_id,created_at);
